questionvariables.text:
/* Design backwards: AP0=p*r, PB=q*s, CP=p*s, PD0=q*r  => AP0*PB = CP*PD0.
   A solution value x is also drawn; AP = x + b1 and PD = x + b2 with
   b1 = AP0 - x, b2 = PD0 - x. p#q forces PB#CP, so (x+b1)PB = CP(x+b2) is a
   genuine linear equation with unique root x. Generate the admissible
   (p,q,r,s,x) on the fly: lengths in [2,12], chord totals <= 15, constants
   nonzero and |b| <= 6, and x distinct from AP and PD. */
params : sublist(
  create_list([p,q,r,s,xx], p,1,4, q,1,4, r,2,5, s,2,5, xx,2,9),
  lambda([z], is(
        z[1]#z[2] and z[3]#z[4]
    and z[1]*z[3]>=2 and z[1]*z[3]<=12 and z[2]*z[4]>=2 and z[2]*z[4]<=12
    and z[1]*z[4]>=2 and z[1]*z[4]<=12 and z[2]*z[3]>=2 and z[2]*z[3]<=12
    and z[1]*z[3]+z[2]*z[4]<=15 and z[1]*z[4]+z[2]*z[3]<=15
    and z[5]#z[1]*z[3] and z[5]#z[2]*z[3]
    and abs(z[1]*z[3]-z[5])<=6 and abs(z[2]*z[3]-z[5])<=6 )));
sel : rand(params);
AP : sel[1]*sel[3];
PB : sel[2]*sel[4];
CP : sel[1]*sel[4];
PD : sel[2]*sel[3];
xsol : sel[5];
b1 : AP - xsol;
b2 : PD - xsol;
eAP : x + b1;
ePD : x + b2;
ta_x : xsol;
ta_AP : AP;
ta_PD : PD;
